#!/bin/bash
#
# @generated by scripts/build-raycast-text-paste-scripts.py
# Source: raycast/text/rewrite-descriptions.txt
# Do not edit this file — edit the source and re-run ./scripts/build-raycast-text-paste-scripts.py
#
# Required parameters:
# @raycast.schemaVersion 1
# @raycast.title rewrite descriptions
# @raycast.mode silent
# @raycast.packageName Text

# Optional parameters:
# @raycast.icon 📋

# Documentation:
# @raycast.description Paste the "rewrite descriptions" text into the frontmost app
# @raycast.author joshlebed
# @raycast.authorURL https://github.com/joshlebed

# Raycast runs scripts without a UTF-8 locale; without this, pbcopy/pbpaste
# transcode non-ASCII text to MacRoman — 🤖 pastes as "ü§ñ".
#
# LC_ALL has to be cleared, not just overridden: it outranks LC_CTYPE, so
# exporting LC_CTYPE alone is silently a no-op whenever anything in the
# environment exports LC_ALL. (LANG is harmless — LC_CTYPE already beats it.)
unset LC_ALL
export LC_CTYPE=UTF-8

ORIGINAL=$(pbpaste)

TEXT=$(cat <<'RAYCAST_TEXT'
for each PR in the stack:

rewrite the PR description to be more clear and put the important stuff up front, as concisely as possible. what is the architectural and behavioral change? what problem is it solving? how is it implemented? what is the most important interface or API changing in the PR? what is the biggest complexity in this PR? what is the most controversial design decision? what are the biggest risks?

answer all of these while staying concise and readable.
RAYCAST_TEXT
)

printf '%s' "$TEXT" | pbcopy
osascript -e 'tell application "System Events" to keystroke "v" using command down'

# Give the paste time to land before putting the clipboard back. Restores text
# only — a non-text clipboard (an image, files) is not preserved.
sleep 0.15
printf '%s' "$ORIGINAL" | pbcopy
